"""Reports generated by agent runs: view, PDF, Excel, email preview, send by email / Microsoft Teams, submit for approval."""
from fastapi import APIRouter, Body, Depends, HTTPException, Query
from fastapi.responses import Response
from sqlalchemy import text

from ..deps import envelope, get_engine, query, require_api_key
from ..factory import notify, reports
from ..factory.users import require
from ..twin.scenarios import audit

router = APIRouter(tags=["reports"], dependencies=[Depends(require_api_key)])


def _rep(rid: str) -> dict:
    r = query("SELECT report_id, run_id, category, title, audience, scope, priority, status, content, generated_by, created_at FROM twin.report WHERE report_id = :i", i=rid)
    if not r:
        raise HTTPException(404, "report not found")
    return {**r[0], "run_id": str(r[0]["run_id"]) if r[0]["run_id"] else None}


@router.get("/reports")
def list_reports(category: str | None = None, run_id: str | None = None, limit: int = Query(default=100, ge=1, le=500)):
    rows = query("SELECT report_id, run_id, category, title, audience, scope, priority, status, generated_by, created_at, "
                 "jsonb_array_length(content->'findings') AS findings, jsonb_array_length(content->'recommendations') AS recommendations "
                 "FROM twin.report WHERE (CAST(:c AS text) IS NULL OR category = :c) AND (CAST(:r AS text) IS NULL OR CAST(run_id AS text) = :r) "
                 "ORDER BY created_at DESC, report_id LIMIT :n", c=category, r=run_id, n=limit)
    return envelope("LIVE", validation_status="NOT_APPLICABLE", items=[{**r, "run_id": str(r["run_id"]) if r["run_id"] else None} for r in rows],
                    categories=[{"id": k, "title": v[0], "audience": v[1]} for k, v in reports.CATEGORIES.items()], channels=notify.channel_status())


@router.get("/reports/{report_id}")
def get_report(report_id: str):
    return envelope("LIVE", validation_status="NOT_APPLICABLE", report=_rep(report_id),
                    notifications=query("SELECT id, channel, recipients, subject, status, error, actor, created_at, sent_at FROM twin.notification "
                                        "WHERE report_id = :i ORDER BY id DESC", i=report_id))


@router.get("/reports/{report_id}/pdf")
def report_pdf(report_id: str):
    rep = _rep(report_id)
    return Response(reports.to_pdf(rep), media_type="application/pdf", headers={"Content-Disposition": f'attachment; filename="{report_id}.pdf"'})


@router.get("/reports/{report_id}/xlsx")
def report_xlsx(report_id: str):
    rep = _rep(report_id)
    return Response(reports.to_xlsx(rep), media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    headers={"Content-Disposition": f'attachment; filename="{report_id}.xlsx"'})


@router.get("/reports/{report_id}/email-preview")
def email_preview(report_id: str):
    subject, body = reports.email_text(_rep(report_id))
    return envelope("LIVE", validation_status="NOT_APPLICABLE", subject=subject, body=body, channels=notify.channel_status())


@router.post("/reports/{report_id}/notify")
def notify_report(report_id: str, body: dict = Body(...), user=Depends(require("ENGINEER"))):
    """{channel: EMAIL|TEAMS, recipients?}: prepares the message, then sends it if the channel is configured. Never reports a fake send."""
    ch = str(body.get("channel", "")).upper()
    if ch not in ("EMAIL", "TEAMS"):
        raise HTTPException(422, "channel must be EMAIL or TEAMS")
    rep = _rep(report_id)
    subject, text_body = reports.email_text(rep)
    to = (body.get("recipients") or "").strip() or None
    if ch == "EMAIL" and to and len(to) > 500:
        raise HTTPException(422, "too many recipients")
    n = notify.prepare(ch, subject, text_body, user["user_id"], to, rep["run_id"], report_id)
    res = notify.send(n["id"], user["user_id"], to)
    return envelope("LIVE", validation_status="NOT_APPLICABLE", notification=res)


@router.post("/reports/{report_id}/submit")
def submit_report(report_id: str, user=Depends(require("ENGINEER"))):
    """Marks the report SUBMITTED for approval; its recommendations are decided individually in the approval queue."""
    rep = _rep(report_id)
    if rep["status"] == "SUBMITTED":
        raise HTTPException(409, "report already submitted")
    with get_engine().begin() as c:
        c.execute(text("UPDATE twin.report SET status = 'SUBMITTED' WHERE report_id = :i"), dict(i=report_id))
        audit(c, user["user_id"], "REPORT_SUBMITTED", "report", report_id, {"recommendations": len(rep["content"].get("recommendations", []))})
    return envelope("LIVE", validation_status="NOT_APPLICABLE", report=_rep(report_id))


@router.get("/notifications")
def notifications(limit: int = Query(default=50, ge=1, le=200)):
    return envelope("LIVE", validation_status="NOT_APPLICABLE", channels=notify.channel_status(),
                    items=query("SELECT id, run_id, report_id, channel, recipients, subject, status, error, actor, created_at, sent_at FROM twin.notification "
                                "ORDER BY id DESC LIMIT :n", n=limit))


@router.get("/notifications/{nid}")
def notification(nid: int):
    r = query("SELECT * FROM twin.notification WHERE id = :i", i=nid)
    if not r:
        raise HTTPException(404, "notification not found")
    return envelope("LIVE", validation_status="NOT_APPLICABLE", notification=r[0])


@router.post("/notifications/{nid}/send")
def send_notification(nid: int, body: dict = Body(default={}), user=Depends(require("ENGINEER"))):
    try:
        return envelope("LIVE", validation_status="NOT_APPLICABLE", notification=notify.send(nid, user["user_id"], (body or {}).get("recipients")))
    except LookupError:
        raise HTTPException(404, "notification not found")
